import React, { useState } from "react";

function About() {
  const [hoveredCard, setHoveredCard] = useState(null);

  const features = [
    { icon: "📝", title: "AI Worksheets", desc: "Generate AI-powered worksheets instantly. Free and accessible to everyone — no login required.", color: "#38bdf8", badge: "Public" },
    { icon: "🎮", title: "Interactive Games", desc: "Learn through fun, engaging games. Sign in to track your progress and compete on leaderboards.", color: "#a855f7", badge: "Login Required" },
    { icon: "👨‍🏫", title: "Live Tutors", desc: "Connect with real tutors for one-on-one guidance and personalized support.", color: "#38bdf8", badge: "Login Required" },
    { icon: "📊", title: "Progress Tracking", desc: "Watch your skills grow with detailed analytics and insights tailored to your learning journey.", color: "#a855f7", badge: "Login Required" },
  ];

  return (
    <section className="page fade-in">
      <div style={{ maxWidth: "1000px", margin: "0 auto" }}>
        <div className="slide-up" style={{ marginBottom: "4rem", textAlign: "center" }}>
          <h1 style={{ fontSize: "3.5rem", fontWeight: "700", marginBottom: "1rem", marginTop: "0", background: "linear-gradient(135deg, #38bdf8 0%, #a855f7 100%)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text" }}>
            About SciHub
          </h1>
          <p style={{ fontSize: "1.15rem", color: "#9ca3af", marginBottom: "0", maxWidth: "700px", margin: "0 auto", lineHeight: "1.8" }}>
            SciHub is a modern science learning platform built by students, for students. 
            Our mission is to make science feel less intimidating and more like a journey 
            of discovery. Try our free AI worksheets instantly — or sign in to unlock interactive games, live tutoring, and personalized learning features.
          </p>
        </div>

        {/* Core Values */}
        <div style={{ marginBottom: "4rem" }}>
          <h2 style={{ fontSize: "2rem", marginBottom: "2rem", color: "#f9fafb", textAlign: "center" }}>Our Core Values</h2>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "1.5rem" }}>
            {[
              { emoji: "👥", title: "Student‑Driven", desc: "Designed with real student feedback to make learning feel natural and motivating." },
              { emoji: "🔬", title: "Science‑Focused", desc: "Every feature is built to help you understand physics, chemistry, and biology deeply." },
              { emoji: "🌐", title: "Accessible", desc: "Works beautifully on laptops, tablets, and phones — anytime, anywhere." },
            ].map((value, i) => (
              <div
                key={i}
                className="card"
                style={{
                  padding: "2rem",
                  animation: `slideUp 0.7s ease forwards`,
                  animationDelay: `${i * 0.1}s`,
                  opacity: 0,
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  transform: hoveredCard === `value-${i}` ? "translateY(-8px)" : "translateY(0)",
                  boxShadow: hoveredCard === `value-${i}` ? "0 20px 50px rgba(56, 189, 248, 0.25)" : "0 18px 40px rgba(15, 23, 42, 0.9)",
                }}
                onMouseEnter={() => setHoveredCard(`value-${i}`)}
                onMouseLeave={() => setHoveredCard(null)}
              >
                <div style={{ fontSize: "2.5rem", marginBottom: "1rem" }}>{value.emoji}</div>
                <h3 style={{ fontSize: "1.3rem", marginTop: "0", marginBottom: "0.8rem", color: "#38bdf8" }}>{value.title}</h3>
                <p style={{ color: "#f9fafb", marginBottom: "0", fontSize: "0.95rem", lineHeight: "1.6" }}>{value.desc}</p>
              </div>
            ))}
          </div>
          <style>{`
            @keyframes slideUp {
              from { opacity: 0; transform: translateY(20px); }
              to { opacity: 1; transform: translateY(0); }
            }
          `}</style>
        </div>

        {/* Features Section */}
        <div>
          <h2 style={{ fontSize: "2rem", marginBottom: "2rem", color: "#f9fafb", textAlign: "center" }}>Why Choose SciHub</h2>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))", gap: "1.5rem" }}>
            {features.map((feature, i) => (
              <div
                key={i}
                style={{
                  background: `linear-gradient(135deg, rgba(56, 189, 248, 0.1) 0%, rgba(168, 85, 247, 0.1) 100%)`,
                  border: `2px solid ${feature.color}`,
                  borderRadius: "16px",
                  padding: "2rem",
                  textAlign: "center",
                  cursor: "pointer",
                  animation: `slideUp 0.7s ease forwards`,
                  animationDelay: `${i * 0.15}s`,
                  opacity: 0,
                  transition: "all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)",
                  transform: hoveredCard === `feature-${i}` ? "scale(1.05) translateY(-12px)" : "scale(1) translateY(0)",
                  boxShadow: hoveredCard === `feature-${i}` ? `0 20px 60px ${feature.color}40` : "0 10px 30px rgba(15, 23, 42, 0.5)",
                }}
                onMouseEnter={() => setHoveredCard(`feature-${i}`)}
                onMouseLeave={() => setHoveredCard(null)}
              >
                <div style={{ 
                  fontSize: "3rem", 
                  marginBottom: "1rem",
                  display: "inline-block",
                  transition: "transform 0.3s ease",
                  transform: hoveredCard === `feature-${i}` ? "rotate(10deg) scale(1.2)" : "rotate(0deg) scale(1)",
                }}>
                  {feature.icon}
                </div>
                <h3 style={{ fontSize: "1.25rem", marginTop: "0", marginBottom: "0.8rem", color: feature.color }}>{feature.title}</h3>
                <p style={{ color: "#f9fafb", marginBottom: "0", fontSize: "0.95rem", lineHeight: "1.6" }}>{feature.desc}</p>
              </div>
            ))}
          </div>
        </div>

        {/* CTA Section */}
        <div style={{ 
          marginTop: "4rem", 
          textAlign: "center",
          padding: "3rem 2rem",
          background: "linear-gradient(135deg, rgba(56, 189, 248, 0.15) 0%, rgba(168, 85, 247, 0.15) 100%)",
          borderRadius: "20px",
          border: "1px solid rgba(56, 189, 248, 0.3)",
          animation: "slideUp 0.8s ease forwards",
          animationDelay: "0.6s",
          opacity: 0,
        }}>
          <h2 style={{ fontSize: "1.8rem", marginTop: "0", marginBottom: "1rem", color: "#f9fafb" }}>Ready to Transform Your Learning?</h2>
          <p style={{ fontSize: "1.05rem", color: "#9ca3af", marginBottom: "0" }}>
            Join thousands of students discovering science in a whole new way. Start your journey today.
          </p>
        </div>
      </div>
    </section>
  );
}

export default About;
